//! 🧪️ Genuine captured aliases survive every paid prefix and receive actual supplied context deltas once.
use semio_framework_job::*;
use semio_framework_value::{ValueError,ValueRefusalKind};
use semio_framework_async::CancelTokenRetirement;
#[global_allocator]
static ORIGINAL_SOURCE_HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;

fn observe<T>(run:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(run);(value,(heap.requested_bytes,heap.released_bytes))}
fn now()->Option<u64>{Some(1)}
#[test]
fn original_caller_capture_preserves_paid_aliases_supplier_identity_and_exact_receiving(){
 let policy:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🎟️caller.json")).unwrap();let grant:RetainedCloneGrant=serde_json::from_value(policy["grant"].clone()).unwrap();let operation=OperationId(policy["operation"].as_u64().unwrap());let generation=Generation(policy["generation"].as_u64().unwrap());let budget=||StepBudget::new(policy["fuel"].as_u64().unwrap(),policy["deadlineUs"].as_u64().unwrap(),grant);
 for cut in policy["captureCuts"].as_array().unwrap(){let cut=cut.as_u64().unwrap();let((cancel,root_birth),heap)=observe(||CancelToken::admit_root(grant).unwrap().unwrap());assert_eq!(heap,(root_birth.retained_capacity_bytes,0));let mut born=heap.0;let mut released=0;let((mut authority,ledger_birth),heap)=observe(||JobPayloadAuthority::admit(operation,generation,grant).unwrap().unwrap());assert_eq!(heap,(ledger_birth.retained_capacity_bytes,0));born+=heap.0;let ledger_pointer=authority.identity().unwrap();let mut sequence=0;let mut recipient=Default::default();let context=StepContext::with_payload_authority(operation,generation,budget(),&cancel,now,&mut sequence,&mut recipient,&authority).unwrap();let(mut capture,heap)=observe(||OriginalCallerCapture::begin(&authority,&cancel,&context).unwrap());assert_eq!(heap,(0,0));drop(context);
  for _ in 0..cut{let mut recipient=Default::default();let mut context=StepContext::with_payload_authority(operation,generation,budget(),&cancel,now,&mut sequence,&mut recipient,&authority).unwrap();let(_,heap)=observe(||capture.advance(&mut context).unwrap());assert_eq!(heap,(0,0));assert_eq!(context.retained_progress(),metadata());assert_eq!(authority.identity().unwrap(),ledger_pointer);}
  if cut<2{cancel.cancel_now();for _ in 0..4{if capture.terminal_is_empty(){break}let mut recipient=Default::default();let mut context=StepContext::with_payload_authority(operation,generation,budget(),&cancel,now,&mut sequence,&mut recipient,&authority).unwrap();let(step,heap)=observe(||capture.close_step(&mut context).unwrap());assert_eq!(heap,(0,0));assert_eq!(context.retained_progress(),step.progress());}assert!(capture.terminal_is_empty());assert_eq!(observe(||drop(capture)).1,(0,0));}
  else{let(mut original,mut issuer)=match capture.finish(){Ok(value)=>value,Err(_)=>panic!("funded capture must finish")};let mut recipient=Default::default();let mut context=StepContext::with_payload_authority(operation,generation,budget(),&cancel,now,&mut sequence,&mut recipient,&authority).unwrap();let pointer=context.original_recipient_identity();let(returned,heap)=observe(||issuer.issue(&original,&mut context).unwrap().close(grant,|same|{assert_eq!(same.original_recipient_identity(),pointer);same.consume_retained(metadata())?;same.consume_fuel(1);Ok(InteractiveJobCloseStep::Pending{progress:metadata()})}));assert_eq!(heap,(0,0));assert!(returned.receipt_refusal().is_none());assert_eq!(context.retained_progress(),metadata());assert_eq!(returned.into_original().unwrap().unwrap().progress(),metadata());drop(context);
   let mut failed_source=None;let failed_progress=RetainedCloneProgress{copied_items:1,retained_capacity_bytes:17,..Default::default()};let mut recipient=Default::default();let mut context=StepContext::with_payload_authority(operation,generation,budget(),&cancel,now,&mut sequence,&mut recipient,&authority).unwrap();let(returned,heap)=observe(||issuer.issue(&original,&mut context).unwrap().close(grant,|same|{let mut source=Vec::<u8>::new();source.try_reserve_exact(17).unwrap();failed_source=Some(source);Err(OriginalTurnFailure::debit_original(ValueError::literal(ValueRefusalKind::InvalidValue,"original capture failed child").with_retained_progress(failed_progress),same))}));assert_eq!(heap,(17,0));born+=heap.0;assert_eq!(context.retained_progress(),failed_progress);let failure=returned.into_original().unwrap().unwrap_err();assert!(failure.receipt_refusal.is_none());assert_eq!(failure.primary.message(),"original capture failed child");assert_eq!(observe(||drop(failure)).1,(0,0));drop(context);
   let mut recipient=Default::default();let mut context=StepContext::with_payload_authority(operation,generation,budget(),&cancel,now,&mut sequence,&mut recipient,&authority).unwrap();let progress=RetainedCloneProgress{copied_items:1,released_bytes:failed_source.as_ref().unwrap().capacity(),..Default::default()};assert!(progress.fits(context.retained_grant()));let((),heap)=observe(||{context.consume_retained(progress).unwrap();drop(failed_source.take());});assert_eq!(heap,(0,17));released+=heap.1;drop(context);
   let mut recipient=Default::default();let mut context=StepContext::with_payload_authority(operation,generation,budget(),&cancel,now,&mut sequence,&mut recipient,&authority).unwrap();let(returned,heap)=observe(||issuer.issue(&original,&mut context).unwrap().close(grant,|_|Ok(InteractiveJobCloseStep::Pending{progress:metadata()})));assert_eq!(heap,(0,0));assert!(returned.admitted().is_none());assert!(returned.receipt_refusal().is_some());assert_eq!(context.retained_progress(),Default::default());assert_eq!(observe(||drop(returned)).1,(0,0));drop(context);
   let((mut foreign,_),heap)=observe(||JobPayloadAuthority::admit(operation,generation,grant).unwrap().unwrap());born+=heap.0;let mut recipient=Default::default();let mut context=StepContext::with_payload_authority(operation,generation,budget(),&cancel,now,&mut sequence,&mut recipient,&foreign).unwrap();assert!(issuer.issue(&original,&mut context).is_err());assert_eq!(context.retained_progress(),Default::default());drop(context);let(step,heap)=observe(||foreign.close_step(grant).unwrap());assert_eq!(heap,(0,step.progress().released_bytes));released+=heap.1;assert_eq!(observe(||drop(foreign)).1,(0,0));
   let((foreign_cancel,_),heap)=observe(||CancelToken::admit_root(grant).unwrap().unwrap());born+=heap.0;let mut recipient=Default::default();let mut context=StepContext::with_payload_authority(operation,generation,budget(),&foreign_cancel,now,&mut sequence,&mut recipient,&authority).unwrap();assert!(issuer.issue(&original,&mut context).is_err());assert_eq!(context.retained_progress(),Default::default());drop(context);let mut foreign_cancel=CancelTokenRetirement::from_token(foreign_cancel);for _ in 0..4{if foreign_cancel.terminal_is_empty(){break}let(step,heap)=observe(||foreign_cancel.close_step(grant).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));released+=heap.1;}assert!(foreign_cancel.terminal_is_empty());assert_eq!(observe(||drop(foreign_cancel)).1,(0,0));
   cancel.cancel_now();for _ in 0..4{if original.terminal_is_empty(){break}let mut recipient=Default::default();let mut context=StepContext::with_payload_authority(operation,generation,budget(),&cancel,now,&mut sequence,&mut recipient,&authority).unwrap();let(step,heap)=observe(||original.close_step(&mut issuer,&mut context).unwrap());assert_eq!(heap,(0,0));assert_eq!(context.retained_progress(),step.progress());}assert!(original.terminal_is_empty());assert_eq!(observe(||drop(original)).1,(0,0));
  }
  let(step,heap)=observe(||authority.close_step(grant).unwrap());assert_eq!(heap,(0,step.progress().released_bytes));released+=heap.1;assert_eq!(observe(||drop(authority)).1,(0,0));let mut root=CancelTokenRetirement::from_token(cancel);for _ in 0..4{if root.terminal_is_empty(){break}let(step,heap)=observe(||root.close_step(grant).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));released+=heap.1;}assert!(root.terminal_is_empty());assert_eq!(observe(||drop(root)).1,(0,0));assert_eq!(born,released);
 }
}

fn metadata()->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,..Default::default()}}
